import React from "react";

export default function Header({ title, subtitle, right, className = "" }) {
  return (
    <header className={`flex items-center justify-between mb-6 px-2 md:px-0 ${className}`}>
      <div>
        <h2 className="text-2xl font-bold text-gray-900 tracking-tight">{title}</h2>
        {subtitle && <div className="text-sm text-gray-500 mt-1">{subtitle}</div>}
      </div>
      {right && <div>{right}</div>}
    </header>
  );
}
